import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

import { AuthProvider } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';

import Login from './pages/Login';
import Register from './pages/Register';
import PatientDashboard from './pages/patient/PatientDasboard';

// Dashboards — we'll build these in Step 4
// Placeholder components for now
// const PatientDashboard    = () => <h2 style={{padding:'2rem'}}>Patient Dashboard 🧑‍⚕️</h2>;
// const DoctorDashboard     = () => <h2 style={{padding:'2rem'}}>Doctor Dashboard 👨‍⚕️</h2>;
const PharmacistDashboard = () => <h2 style={{padding:'2rem'}}>Pharmacist Dashboard 💊</h2>;
const AdminDashboard      = () => <h2 style={{padding:'2rem'}}>Admin Dashboard ⚙️</h2>;

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <Routes>
          {/* Public routes */}
          <Route path="/"         element={<Navigate to="/login" replace />} />
          <Route path="/login"    element={<Login />} />
          <Route path="/register" element={<Register />} />

          {/* Protected routes */}
          <Route
            path="/patient/dashboard"
            element={
              <ProtectedRoute allowedRoles={['patient']}>
                <PatientDashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/doctor/dashboard"
            element={
              <ProtectedRoute allowedRoles={['doctor']}>
                <DoctorDashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/pharmacist/dashboard"
            element={
              <ProtectedRoute allowedRoles={['pharmacist']}>
                <PharmacistDashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/admin/dashboard"
            element={
              <ProtectedRoute allowedRoles={['admin']}>
                <AdminDashboard />
              </ProtectedRoute>
            }
          />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
